// src/components/NavBar.js
import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import styled from 'styled-components';

// Style the NavBar for a beautiful layout
const Nav = styled.nav`
  background: #282c34;
  padding: 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
`;

const NavLinks = styled.ul`
  list-style: none;
  display: flex;
  gap: 20px;
  margin: 0;
  padding: 0;
`;

const NavLink = styled.li`
  a {
    color: #ffffff;
    text-decoration: none;
    font-size: 18px;
    &:hover {
      text-decoration: underline;
    }
  }
`;

const LogoutButton = styled.button`
  background-color: #e63946;
  color: #fff;
  border: none;
  padding: 10px 20px;
  cursor: pointer;
  font-size: 16px;
  border-radius: 4px;

  &:hover {
    background-color: #d62828;
  }
`;

const NavBar = () => {
  const navigate = useNavigate();
  const token = localStorage.getItem('token');

  const handleSignOut = () => {
    localStorage.removeItem('token');  // Remove token from localStorage
    navigate('/');  // Navigate back to home
  };

  return (
    <Nav>
      <NavLinks>
        <NavLink><Link to="/">Home</Link></NavLink>
        <NavLink><Link to="/products">Explore Products</Link></NavLink>
        <NavLink><Link to="/how-to-sign-up">How to Sign Up for a Triathlon</Link></NavLink> {/* New Link */}
      </NavLinks>

      {/* Show login/signup or sign out depending on authentication status */}
      <NavLinks>
        {!token ? (
          <>
            <NavLink><Link to="/login">Login</Link></NavLink>
            <NavLink><Link to="/signup">Sign Up</Link></NavLink>
          </>
        ) : (
          <LogoutButton onClick={handleSignOut}>Sign Out</LogoutButton>
        )}
      </NavLinks>
    </Nav>
  );
};

export default NavBar;
